package com.buildertoolbox.client;
import java.nio.file.*;import java.util.*;import com.google.gson.*;import com.buildertoolbox.client.settings.Setting;import com.buildertoolbox.client.systems.modules.Modules;import net.fabricmc.loader.api.FabricLoader;import net.minecraft.registry.Registries;import net.minecraft.util.Identifier;import net.minecraft.block.Block;
public final class Config {private static final Gson GSON=new GsonBuilder().setPrettyPrinting().create();private static final Path FILE=FabricLoader.getInstance().getConfigDir().resolve("map-art-tools.json");private static boolean loading;
 private static boolean command(Setting<?> s){return s.name.startsWith("Select ")||s.name.startsWith("Set ")||s.name.equals("Reset Batch")||s.name.equals("Start / Resume");}
 public static void save(){if(loading)return;try{var root=new JsonObject();for(var m:Modules.get().getAll()){var data=new JsonObject();for(var group:m.settings)for(var s:group)if(!command(s))data.addProperty(s.name,display(s));root.add(m.name,data);}var windows=new JsonObject();for(var entry:com.buildertoolbox.client.gui.GuiThemes.get().windows.entrySet()){var w=new JsonObject();w.addProperty("x",entry.getValue().x);w.addProperty("y",entry.getValue().y);w.addProperty("expanded",entry.getValue().expanded);windows.add(entry.getKey(),w);}root.add("$windows",windows);Files.createDirectories(FILE.getParent());Path temp=FILE.resolveSibling(FILE.getFileName()+".tmp");Files.writeString(temp,GSON.toJson(root));try{Files.move(temp,FILE,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,FILE,StandardCopyOption.REPLACE_EXISTING);}}catch(Exception e){com.buildertoolbox.BuilderToolboxAddon.LOG.error("Could not save settings",e);}}
 public static void load(){if(!Files.isRegularFile(FILE))return;loading=true;try{var root=JsonParser.parseString(Files.readString(FILE)).getAsJsonObject();if(root.has("$windows")){for(var entry:root.getAsJsonObject("$windows").entrySet()){var data=entry.getValue().getAsJsonObject();var w=com.buildertoolbox.client.gui.GuiThemes.get().getWindowConfig(entry.getKey());w.x=data.get("x").getAsDouble();w.y=data.get("y").getAsDouble();w.expanded=data.get("expanded").getAsBoolean();}}for(var m:Modules.get().getAll()){var data=root.getAsJsonObject(m.name);if(data==null)continue;for(var g:m.settings)for(var s:g)if(!command(s)&&data.has(s.name))try{edit(s,data.get(s.name).getAsString());}catch(RuntimeException e){com.buildertoolbox.BuilderToolboxAddon.LOG.warn("Invalid setting {}",s.name,e);}}}catch(Exception e){com.buildertoolbox.BuilderToolboxAddon.LOG.error("Could not load settings",e);}finally{loading=false;}}
 public static String display(Setting<?> s){Object v=s.get();if(v instanceof List<?> l)return String.join("; ",l.stream().map(x->x instanceof Block b?Registries.BLOCK.getId(b).toString():x.toString()).toList());if(v instanceof com.buildertoolbox.client.utils.render.color.Color c)return c.r+","+c.g+","+c.b+","+c.a;return String.valueOf(v);}
 @SuppressWarnings({"unchecked","rawtypes"}) public static void edit(Setting s,String text){Object v=s.get(),parsed=text;if(v instanceof Integer)parsed=Integer.valueOf(text);else if(v instanceof Double)parsed=Double.valueOf(text);else if(v instanceof Boolean)parsed=Boolean.valueOf(text);else if(v instanceof Enum e)parsed=Enum.valueOf(e.getDeclaringClass(),text);else if(v instanceof List l){List result=new ArrayList();for(String entry:text.split(";"))if(!entry.isBlank()){String trimmed=entry.trim();result.add(!l.isEmpty()&&l.getFirst() instanceof Block?Registries.BLOCK.get(Identifier.of(trimmed)):trimmed);}parsed=result;}else if(v instanceof com.buildertoolbox.client.utils.render.color.Color){String[] a=text.split(",");parsed=new com.buildertoolbox.client.utils.render.color.SettingColor(Integer.parseInt(a[0]),Integer.parseInt(a[1]),Integer.parseInt(a[2]),a.length>3?Integer.parseInt(a[3]):255);}s.set(parsed);}
}